<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Lumina · Staff workspace</title><link rel="stylesheet" href="/assets/css/app.css?v={{app_css_version}}"><link rel="stylesheet" href="/assets/css/staff.css?v={{staff_css_version}}"><link rel="stylesheet" href="/assets/css/ui-feedback.css"><script src="/assets/js/ui-feedback.js" defer></script><script src="/assets/js/floor-layout.js?v={{floor_version}}" defer></script><script src="/assets/js/staff.js?v={{staff_version}}" defer></script></head>
<body class="staff-body" data-view="{{view}}">
<a class="skip-link" href="#staff-main">Skip to workspace</a>
<header class="staff-header"><a class="brand" href="/"><svg viewBox="0 0 32 32" width="32" height="32" aria-hidden="true"><circle cx="16" cy="16" r="14.5" fill="none" stroke="currentColor"/><path d="M16 6.5C19.6 11 21.4 13.6 21.4 17a5.4 5.4 0 0 1-10.8 0c0-3.4 1.8-6 5.4-10.5Z" fill="currentColor"/></svg><span><b>Lumina</b><small>Staff workspace</small></span></a><div class="staff-identity"><span id="staff-user"></span><a href="/">Guest site ↗</a><button class="button ghost small" id="staff-logout" hidden>Sign out</button></div></header>
<div class="staff-layout"><aside id="staff-sidebar" hidden><p class="eyebrow">Service operations</p><nav aria-label="Staff workspace"><button data-tab="service" aria-current="page">Service overview</button><button data-tab="waitlist">Waitlist</button><button data-tab="settings">Booking settings</button><button data-tab="staff">Staff accounts</button><button data-tab="audit">Audit history</button><button data-tab="outbox">Demo notifications</button></nav><p class="sidebar-note">Restaurant time<br><strong>Asia/Manila</strong><br><br>Fictional demo venue.<br>No real messages or payments.</p></aside>
<main id="staff-main" tabindex="-1"><p id="staff-feedback" class="feedback" role="alert" tabindex="-1" hidden></p><div id="staff-workspace"><p class="loading">Loading workspace…</p></div><noscript><p>Enable JavaScript to use the staff workspace.</p></noscript></main></div>
<dialog id="staff-dialog" aria-labelledby="staff-dialog-title"><header class="dialog-header"><h2 id="staff-dialog-title"></h2><button class="button ghost small" id="staff-close-dialog" aria-label="Close dialog">Close</button></header><p id="dialog-feedback" class="feedback" role="alert" tabindex="-1" hidden></p><div id="staff-dialog-content"></div></dialog>
</body></html>
